#!/usr/bin/env bash
# PostToolUse: after an edit under src/ or to pom.xml, run the fast tests (everything except
# @Tag("slow")) and feed failures back to Claude. The tool has already run; this cannot undo it.
set -uo pipefail
ROOT="${CLAUDE_PROJECT_DIR:-$(pwd)}"
payload="$(cat)"
path="$(jq -r '.tool_input.file_path // .tool_input.notebook_path // empty' <<<"$payload")"
[[ -z "$path" ]] && exit 0
[[ "$path" != /* ]] && path="$(jq -r '.cwd // empty' <<<"$payload")/$path"
case "$path" in
  "$ROOT"/src/*|"$ROOT"/pom.xml) ;;
  *) exit 0 ;;
esac

cd "$ROOT" || exit 0
if output="$(./mvnw -q test -DexcludedGroups=slow 2>&1)"; then
  exit 0
fi
jq -n --arg out "$(tail -n 60 <<<"$output")" \
  '{decision: "block", reason: ("Fast tests failed after this edit (./mvnw -q test -DexcludedGroups=slow):\n" + $out)}'
exit 0
#!/usr/bin/env bash
# Stop: run the full suite except @Tag("wip") before Claude finishes a turn. If it fails, block
# the stop so Claude fixes it. Tests tagged wip (written before their code) never block.
# Loop guard: stop_hook_active is true when Claude is already continuing because of this hook,
# so a second failure lets the turn end instead of looping (Claude Code also caps consecutive
# blocks at 8).
set -uo pipefail
ROOT="${CLAUDE_PROJECT_DIR:-$(pwd)}"
payload="$(cat)"
[[ "$(jq -r '.stop_hook_active // false' <<<"$payload")" == "true" ]] && exit 0

cd "$ROOT" || exit 0
STAMP="target/.stop-hook-green"
# Skip when nothing the suite depends on has changed since the last green run.
if [[ -f "$STAMP" ]] && [[ -z "$(find src pom.xml README.md proposal.md obsi-methodology.md \
      -newer "$STAMP" -print -quit 2>/dev/null)" ]]; then
  exit 0
fi

if output="$(./mvnw -q verify -DexcludedGroups=wip 2>&1)"; then
  mkdir -p target && touch "$STAMP"
  exit 0
fi
jq -n --arg out "$(tail -n 80 <<<"$output")" \
  '{decision: "block", reason: ("Test suite failed (./mvnw -q verify -DexcludedGroups=wip). Fix it, or tag a test written ahead of its code with @Tag(\"wip\"):\n" + $out)}'
exit 0
package com.cfbenchmarks.obsi;

import org.junit.jupiter.api.Test;

import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;

import static org.assertj.core.api.Assertions.assertThat;

/** The spec is the source of truth and must never change. See AGENTS.md. */
class SpecIntegrityTest {

    private static final String PINNED_SHA256 =
            "07acba3c91d8e7605949a71c5657a04309324ded56ed1d9a30eac8f9504ee655";

    @Test
    void specMatchesPinnedHash() throws Exception {
        byte[] spec = Files.readAllBytes(Path.of("obsi-methodology.md"));
        String actual = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(spec));
        assertThat(actual)
                .as("obsi-methodology.md has been modified; the spec must not be edited")
                .isEqualTo(PINNED_SHA256);
    }
}

