import java.math.BigDecimal;
import java.util.*;
public class DoubleCheck {
  static boolean a(double m, double med) { return Math.abs(m - med) / med * 100 <= 5; }
  static boolean b(double m, double med) { return Math.abs(m - med) * 100 <= 5 * med; }
  static boolean c(double m, double med) { return 100 * Math.abs(m / med - 1) <= 5; }
  public static void main(String[] x) {
    double m = 3.15, med = 3.0;
    System.out.println("claimed case med=3 m=3.15 (exactly +5%, so all should be true)");
    System.out.println("  |m-med|/med*100 = " + (Math.abs(m - med) / med * 100) + " -> passes? " + a(m, med));
    System.out.println("  |m-med|*100 <= 5*med: " + (Math.abs(m - med) * 100) + " vs " + (5 * med) + " -> passes? " + b(m, med));
    System.out.println("  100*|m/med-1|: " + (100 * Math.abs(m / med - 1)) + " -> passes? " + c(m, med));
    // search exact +5% and -5% boundaries (decimal-exact) where double formulations give the wrong answer
    Random r = new Random(1);
    int na = 0, nb = 0, nc = 0, total = 0;
    List<String> exA = new ArrayList<>(), exB = new ArrayList<>();
    for (int i = 0; i < 200000; i++) {
      // med = k/100 for k in 100..99999 ; m = med*1.05 or med*0.95 exact in decimal when k multiple of 20
      long k = (r.nextInt(5000) + 5) * 20L;      // med in cents, multiple of 20 => 1.05*med exact in cents
      BigDecimal med1 = BigDecimal.valueOf(k, 2);
      for (BigDecimal f : new BigDecimal[]{new BigDecimal("1.05"), new BigDecimal("0.95")}) {
        BigDecimal m1 = med1.multiply(f);
        if (m1.scale() > 4) continue;
        // exact: |m-med|*100 == 5*med
        if (m1.subtract(med1).abs().multiply(BigDecimal.valueOf(100)).compareTo(med1.multiply(BigDecimal.valueOf(5))) != 0) continue;
        total++;
        double dm = m1.doubleValue(), dmed = med1.doubleValue();
        if (!a(dm, dmed)) { na++; if (exA.size() < 3) exA.add(med1 + " / " + m1); }
        if (!b(dm, dmed)) { nb++; if (exB.size() < 3) exB.add(med1 + " / " + m1); }
        if (!c(dm, dmed)) nc++;
      }
    }
    System.out.println("exact boundary cases tried: " + total);
    System.out.println("  (a) |m-med|/med*100 <= 5 wrongly EXCLUDES: " + na + " e.g. " + exA);
    System.out.println("  (b) |m-med|*100 <= 5*med wrongly EXCLUDES: " + nb + " e.g. " + exB);
    System.out.println("  (c) 100*|m/med-1| <= 5 wrongly EXCLUDES: " + nc);
  }
}
