import java.math.BigDecimal;
import java.util.*;

public class DoubleCheck {
    static boolean a(double m, double med) { return Math.abs(m - med) / med * 100 <= 5; }
    static boolean b(double m, double med) { return Math.abs(m - med) * 100 <= 5 * med; }
    static boolean c(double m, double med) { return 100 * Math.abs(m / med - 1) <= 5; }

    public static void main(String[] x) {
        double m = 3.15, med = 3.0;
        System.out.println("claimed case med=3 m=3.15 (exactly +5%, so every formulation should pass)");
        System.out.println("  (a) |m-med|/med*100 = " + (Math.abs(m - med) / med * 100) + " -> passes? " + a(m, med));
        System.out.println("  (b) |m-med|*100 = " + (Math.abs(m - med) * 100) + " vs 5*med = " + (5 * med) + " -> passes? " + b(m, med));
        System.out.println("  (c) 100*|m/med-1| = " + (100 * Math.abs(m / med - 1)) + " -> passes? " + c(m, med));

        Random r = new Random(1);
        int na = 0, nb = 0, nc = 0, total = 0;
        List<String> exA = new ArrayList<>(), exB = new ArrayList<>(), exC = new ArrayList<>();
        for (int i = 0; i < 200000; i++) {
            long k = (r.nextInt(5000) + 5) * 20L; // median in cents, multiple of 20 => +-5% is exact in cents
            BigDecimal med1 = BigDecimal.valueOf(k, 2);
            for (String f : new String[] {"1.05", "0.95"}) {
                BigDecimal m1 = med1.multiply(new BigDecimal(f));
                // exact decimal check: |m-med|*100 == 5*med
                if (m1.subtract(med1).abs().multiply(BigDecimal.valueOf(100))
                        .compareTo(med1.multiply(BigDecimal.valueOf(5))) != 0) continue;
                total++;
                double dm = m1.doubleValue(), dmed = med1.doubleValue();
                if (!a(dm, dmed)) { na++; if (exA.size() < 4) exA.add(med1 + " / " + m1); }
                if (!b(dm, dmed)) { nb++; if (exB.size() < 4) exB.add(med1 + " / " + m1); }
                if (!c(dm, dmed)) { nc++; if (exC.size() < 4) exC.add(med1 + " / " + m1); }
            }
        }
        System.out.println("exact +-5% boundary cases tried: " + total);
        System.out.println("  (a) divide, then compare : wrongly EXCLUDES " + na + "  e.g. " + exA);
        System.out.println("  (b) multiply, no divide  : wrongly EXCLUDES " + nb + "  e.g. " + exB);
        System.out.println("  (c) ratio form           : wrongly EXCLUDES " + nc + "  e.g. " + exC);
    }
}

package com.cfbenchmarks.obsi.book;

import com.cfbenchmarks.obsi.input.Level;

import java.math.BigDecimal;
import java.util.List;
import java.util.Objects;

/**
 * A structurally valid constituent book (spec §2): both sides are non-empty after the entry
 * screen and the best bid is below the best ask. It is what the deviation screen sees and what
 * consolidation (§3) receives for the books that survive.
 *
 * @param exchange the exchange name exactly as given in the input
 * @param bids     the entries that passed the entry screen, in input order (not sorted)
 * @param asks     the entries that passed the entry screen, in input order (not sorted)
 * @param bestBid  the highest bid price, by price and not by position (D-11)
 * @param bestAsk  the lowest ask price, by price and not by position (D-11)
 */
public record ValidBook(String exchange, List<Level> bids, List<Level> asks, BigDecimal bestBid,
                        BigDecimal bestAsk) {

    public ValidBook {
        Objects.requireNonNull(exchange, "exchange");
        bids = List.copyOf(bids);
        asks = List.copyOf(asks);
        Objects.requireNonNull(bestBid, "bestBid");
        Objects.requireNonNull(bestAsk, "bestAsk");
        // §2: a book is only valid with positive prices and best bid < best ask.
        if (bestBid.signum() <= 0 || bestBid.compareTo(bestAsk) >= 0) {
            throw new IllegalArgumentException(
                    "a structurally valid book needs 0 < bestBid < bestAsk, got " + bestBid + " / " + bestAsk);
        }
    }

    /** The top-of-book mid-price m = (best bid + best ask) / 2 (spec §2, §1). */
    public BigDecimal mid() {
        throw new UnsupportedOperationException("not implemented");
    }
}

