        return Optional.of(new ValidBook(book.exchange(), bids, asks, bestBid, bestAsk));
    }

    private static List<Level> strictlyPositive(List<Level> side) {
        return side.stream()
                .filter(level -> level.price().signum() > 0 && level.size().signum() > 0)
                .toList();
    }
}

