        for (BookInput input : snapshot.books()) {
            switch (input) {
                // §2 / D-03: a book whose structure cannot be read is excluded. It is not added here, so it
                // shows up in excludedExchanges below.
                case UnreadableBook _ -> { }
                case ReadableBook readable -> BookScreen.structurallyValid(readable).ifPresent(structurallyValid::add);
            }
        }

        // Deviation screen: only on the structurally valid books (§1: the median is of structurally
        // valid mids), with the snapshot for filters that need more than the books.
        List<ValidBook> deviating = deviationFilter.excluded(List.copyOf(structurallyValid), snapshot);
        Set<String> deviatingNames = new HashSet<>();
        deviating.forEach(book -> deviatingNames.add(book.exchange()));   // names are unique: D-02, D-16

        List<ValidBook> survivors = structurallyValid.stream()
                .filter(book -> !deviatingNames.contains(book.exchange()))
                .toList();

        // §6: the calculation fails if no constituent book survives screening. D-12, D-19: say so when the
        // structurally valid books were all removed by the deviation screen; if none was structurally
        // valid (or there are no books), PED never ran.
        if (survivors.isEmpty()) {
            return new ScreeningResult.Failed(structurallyValid.isEmpty() ? NO_SURVIVOR : NO_SURVIVOR_BY_PED);
        }

        // Brief "Output": excludedExchanges lists every screened-out exchange in input order, names as given.
        Set<String> survivorNames = new HashSet<>();
        survivors.forEach(book -> survivorNames.add(book.exchange()));
        List<String> excluded = snapshot.books().stream()
                .map(BookInput::exchange)
                .filter(name -> !survivorNames.contains(name))
                .toList();
        return new ScreeningResult.Screened(survivors, excluded);
    }
}

