    public static ReadableBook crossedAtMid(String name, String mid) {
        BigDecimal m = new BigDecimal(mid);
        return book(name, m.add(HALF_SPREAD).toPlainString(), m.subtract(HALF_SPREAD).toPlainString());
    }

