    @Tag("wip")
    @Test
    void bothSidesExhaustedFails() {
        ConsolidationResult result = Consolidator.uncross(List.of(lv("105", "1")), List.of(lv("100", "1")));

        assertThat(failureReason(result)).isEqualTo("uncrossing exhausted both sides");
