    void aWellFormedBookIsAccepted() {
        Consolidated book = new Consolidated(
                List.of(lv("99", "1"), lv("98.5", "2")), List.of(lv("100", "1"), lv("100.5", "0.1")));

        assertThat(book.bids()).hasSize(2);
        assertThat(book.asks()).hasSize(2);
    }

