42	            pairs = inputs
43	                    .filter(p -> Files.isRegularFile(p) && p.getFileName().toString().endsWith(".json"))
44	                    .sorted()
45	                    .map(p -> new Path[] {p, EXPECTED.resolve(stem(p) + SUFFIX)})
46	                    .filter(pair -> Files.isRegularFile(pair[1]))
47	                    .toList();
48	        }
49	        return pairs.stream();
50	    }
51	
52	    private static String stem(Path p) {
53	        String name = p.getFileName().toString();
