68	        assertThat(err.toString(StandardCharsets.UTF_8)).as("stderr").isEmpty();
69	        assertThat(exit).as("exit code").isZero();
70	        JsonNode actual = JSON.readTree(out.toString(StandardCharsets.UTF_8));
71	        assertThat(actual).as("stdout JSON").isEqualTo(JSON.readTree(expected.toFile()));
72	    }
73	
74	    /** Guard: a renamed or mistyped file must not turn the golden test into a silent zero-case pass. */
75	    @Test
76	    void everyExpectedFileHasAnInputAndSomePairExists() throws IOException {
77	        List<Path[]> pairs = goldenPairs().toList();
78	        assertThat(pairs).as("input/expected pairs found").isNotEmpty();
79	
80	        List<String> paired = pairs.stream().map(pair -> pair[1].getFileName().toString()).toList();
81	        try (Stream<Path> expected = Files.list(EXPECTED)) {
82	            List<String> orphans = expected
83	                    .map(p -> p.getFileName().toString())
84	                    .filter(n -> n.endsWith(SUFFIX))
85	                    .filter(n -> !paired.contains(n))
86	                    .toList();
87	            assertThat(orphans).as("expected files without a matching input under data/").isEmpty();
88	        }
89	    }
90	}
